// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · Korelasyon ve regresyon (zor).
const ozStatistics11Zor = <(String, String, List<String>, String)>[
  ('x: 10, 20, 30, 40, 50 ve y: 12, 15, 15, 22, 26 verileri için Sxy = 350 ve Sxx = 1000\'dir. Syy = 134 ise Pearson r yaklaşık kaçtır?', '0,96', ['0,345', '0,87', '0,64'], 'r = 350/√(1000·134) = 350/366,1 ≈ 0,956 ≈ 0,96.'),
  ('Çalışma süresi saat cinsinden alınınca ŷ = 40 + 5x elde ediliyor. Süre dakikaya çevrilip modelin yeniden kurulması durumunda eğim ve sabit terim ne olur?', 'Eğim yaklaşık 0,083, sabit terim 40', ['Eğim 300 olur, sabit terim ise 40 kalır', 'Eğim 5, sabit terim 2400', 'Eğim 0,083, sabit terim 0,67'], 'Dakika = 60·saat olduğundan eğim 60\'a bölünür (5/60 ≈ 0,083); x = 0 noktası aynı kaldığı için sabit terim değişmez.'),
  ('27 çiftlik bir örnekte r = 0,6 bulunmuştur. r\'nin sıfırdan farklılığını sınayan t istatistiği t = r√(n−2)/√(1−r²) ile hesaplanırsa değeri kaçtır?', '3,75', ['2,00', '4,50', '0,375'], 't = 0,6·√25/√0,64 = 0,6·5/0,8 = 3,75; serbestlik derecesi 25\'tir.'),
  ('Basit doğrusal regresyonda eğim için yapılan t testinin p değeri ile korelasyon katsayısı için yapılan t testinin p değeri nasıl karşılaştırılır?', 'Aynıdır', ['Eğim testinin p değeri her zaman daha küçüktür', 'Korelasyon testinin p değeri her zaman daha küçüktür', 'Aralarında sabit bir ilişki yoktur'], 'Basit regresyonda b = r·sy/sx olduğundan iki testin t istatistiği özdeştir; dolayısıyla p değerleri de aynıdır.'),
  ('n = 103 ve r = 0,6 için z′ ≈ 0,693 ve SE = 0,1\'dir. %95 güven aralığının z′ cinsinden uçları 0,497 ile 0,889 ise ρ için aralık yaklaşık hangisidir?', '0,46 ile 0,71 arası', ['0,50 ile 0,89 arası', '0,40 ile 0,80 arası', '0,58 ile 0,62 arası'], 'Uçlar tanh ile geri dönüştürülür: tanh(0,497) ≈ 0,46 ve tanh(0,889) ≈ 0,71. Aralık r = 0,6 çevresinde simetrik değildir.'),
  ('Doğru ilişkili iki değişkenin gerçek korelasyonu 0,8, ölçüm güvenirlikleri ise 0,81 ve 0,64\'tür. Ölçüm hatası nedeniyle gözlenen korelasyon yaklaşık kaç olur?', '0,58', ['0,80', '0,41', '0,72'], 'r_gözlenen = r_gerçek·√(r_xx·r_yy) = 0,8·√(0,5184) = 0,8·0,72 = 0,576.'),
  ('Gözlenen korelasyon 0,45, birinci ölçümün güvenirliği 0,81 ve ikincisinin 1,00\'dir. Zayıflama düzeltmesiyle gerçek korelasyon tahmini kaçtır?', '0,50', ['0,41', '0,55', '0,36'], 'r_gerçek = r_gözlenen/√(r_xx·r_yy) = 0,45/0,9 = 0,50.'),
  ('İki varlığın getirilerinin her birinin varyansı 100 ve aralarındaki korelasyon 0,2\'dir. Parayı yarı yarıya bölen portföyün getiri varyansı kaçtır?', '60', ['50', '100', '80'], 'Var = 0,25·100 + 0,25·100 + 2·0,25·0,2·100 = 25 + 25 + 10 = 60.'),
  ('Varyansı 9 olan X\'e, bağımsız ve varyansı 16 olan bir gürültü e eklenerek W = X + e elde ediliyor. X ile W arasındaki korelasyon kaçtır?', '0,6', ['0,36', '0,75', '0,56'], 'Cov(X, W) = Var(X) = 9; sx = 3, sw = 5. r = 9/(3·5) = 0,6.'),
  ('White testi, Breusch–Pagan testinden hangi yönüyle ayrılır?', 'Değişen varyansın belirli bir biçimini önceden varsaymadan genel bir sınama sunar', ['Yalnızca hataların normalliğini sınayarak daha güçlü bir sonuç verir', 'Yalnızca ardışık hataların ilişkisini sınayan bir testtir', 'Yalnız çok küçük örneklerde ve tek değişkenli modellerde kullanılır'], 'White testi açıklayıcıların kareleri ve çarpımlarını da kullanarak daha genel biçimde değişen varyansı arar.'),
  ('Hata terimi ile açıklayıcı değişken ilişkili ise (örneğin önemli bir değişken modelden dışlanmışsa) en küçük kareler katsayıları için ne olur?', 'Katsayılar yanlı ve tutarsız hâle gelir', ['Yalnız standart hatalar değişir, katsayılar yansız kalır', 'R² sıfır olur ve model tümüyle işlevsizleşir', 'Sadece sabit terim etkilenir, eğimler aynı kalır'], 'Dışlanan değişken hata terimine girer ve x ile ilişkiliyse, x\'in katsayısı o değişkenin etkisinin bir kısmını da üstlenir; bu da yanlılık yaratır.'),
  ('Gelirin (x) harcama (y) üzerindeki etkisi incelenirken modele servet atlanmıştır; servet gelirle ve harcamayla pozitif ilişkilidir. Gelirin katsayısı için sapma hangi yöndedir?', 'Olduğundan büyük tahmin edilir (yukarı yönlü yanlılık)', ['Olduğundan küçük tahmin edilir (aşağı yönlü yanlılık)', 'Hiç yanlılık oluşmaz, çünkü servet gelirle ilişkilidir', 'Mutlaka negatif işaretli çıkar ve anlamsız olur'], 'Atlanan değişken x ile aynı yönde ve y ile pozitif ilişkiliyse x\'in katsayısı onun etkisini de içine alır ve şişer.'),
  ('Açıklayıcı değişken x\'in güvenirliği 0,8 olan bir araçla ölçülüyor ve gerçek eğim 5\'tir. Büyük örneklemde ölçüm hatalı x ile kurulan basit regresyonun beklenen eğimi (azalma çarpanı güvenirliktir) kaçtır?', '4', ['5', '6,25', '0,8'], 'Regresyon seyrelmesi: β_gözlenen ≈ β·güvenirlik = 5·0,8 = 4; eğim sıfıra doğru küçülür.'),
  ('DFBETAS ölçüsü neyi gösterir?', 'Bir gözlem çıkarılınca belirli bir katsayının standartlaştırılmış değişimini', ['Gözlemin artığının varyansını ve işaretini', 'Modelin toplam R² değerindeki değişimi', 'Gözlemin kaldıracının karesini ve gözlem sayısını'], 'DFBETAS, i. gözlem silindiğinde j. katsayıda oluşan farkın standart hata cinsinden ifadesidir; katsayı bazında etki ölçer.'),
  ('BIC, AIC\'ye kıyasla parametre sayısını nasıl cezalandırır?', 'Parametre başına ln(n) ceza uygular; n büyüdükçe AIC\'nin 2\'sinden daha ağır olur', ['Parametre sayısına hiç ceza uygulamaz ve yalnız olabilirliğe bakar', 'Parametre başına her zaman 1 birim ceza uygular', 'Parametre başına ceza, n büyüdükçe giderek azalır ve sıfıra yaklaşır'], 'BIC = k·ln(n) − 2lnL; n > 7 olduğunda ln(n) > 2 olduğundan BIC genellikle daha sade modelleri seçer.'),
  ('İç içe iki modelde indirgenmiş modelin SSE\'si 100, tam modelin SSE\'si 80, eklenen parametre sayısı 2 ve tam modelin artık serbestlik derecesi 20\'dir. Kısmi F istatistiği kaçtır?', '2,5', ['10', '0,25', '5'], 'F = [(100−80)/2]/(80/20) = 10/4 = 2,5.'),
  ('Bağımlı değişken için Box–Cox dönüşümünde λ = 0 değeri hangi dönüşüme karşılık gelir?', 'Doğal logaritma dönüşümü', ['Karekök dönüşümü', 'Ters (1/y) dönüşümü', 'Hiç dönüşüm yapılmaması'], 'Box–Cox ailesinde λ → 0 limitinde dönüşüm ln(y) olur; λ = 1 dönüşümsüzdür, λ = 0,5 karekökle ilişkilidir.'),
  ('Klasik varsayımlar altında Gauss–Markov teoremi en küçük kareler tahmin edicisi için neyi söyler?', 'Doğrusal yansız tahmin ediciler arasında en küçük varyanslı olandır', ['Tüm tahmin ediciler arasında en küçük varyanslı olandır', 'Hataların normal olmasını gerektirir ve ancak o zaman yansızdır', 'Yalnızca büyük örneklemlerde yansızdır'], 'Teorem normallik gerektirmez; doğrusal ve yansız tahmin ediciler sınıfında OLS\'nin en küçük varyanslı (en iyi) olduğunu belirtir.'),
  ('Maurice Kendall, sıra korelasyonu için tau katsayısını hangi yıl önerdi?', '1938', ['1888', '1904', '1965'], 'Kendall tau, M. G. Kendall\'ın 1938 tarihli \'A New Measure of Rank Correlation\' makalesiyle tanıtılmıştır.'),
  ('İki değişkenli normal dağılımın ilk matematiksel işlemlerinden birini 1846\'da yapan ve Pearson\'ın katsayısına öncülük ettiği için anılan Fransız bilim insanı kimdir?', 'Auguste Bravais', ['Pierre-Simon Laplace', 'Siméon Denis Poisson', 'Adolphe Quetelet'], 'Bravais, iki değişkenli normal dağılımın parametrelerini inceledi; Pearson, katsayıyı geliştirirken onun katkısını ayrıca belirtmiştir.'),
  ('1920\'lerde nedensel ilişkilerin yönlü diyagramlarla ve korelasyonlarla çözümlendiği \'yol çözümlemesi\' (path analysis) yöntemini geliştiren kişi kimdir?', 'Sewall Wright', ['Karl Pearson', 'Charles Spearman', 'Jerzy Neyman'], 'Genetikçi Sewall Wright, katsayıları yönlü ilişkilerden hesaplayan yol çözümlemesini geliştirdi; bu yöntem sonraki yapısal eşitlik modellerinin temelidir.'),
  ('Tüm nokta çiftlerinden geçen doğruların eğimlerinin ortancasını eğim tahmini olarak alan, uç değerlere dayanıklı yöntem hangi adla bilinir?', 'Theil–Sen tahmin edicisi', ['Pearson tahmin edicisi', 'Fisher tahmin edicisi', 'Bayes tahmin edicisi'], 'Theil–Sen, ikili eğimlerin medyanını alır; bu yüzden birkaç uç gözlemden sıradan en küçük karelere göre çok daha az etkilenir.'),
  ('Bir öğrenci aynı veriden y|x eğimini 2, x|y eğimini 0,6 bulmuştur. Bu sonuç için ne söylenebilir?', 'Hatalıdır; çünkü çarpım 1,2 olup r² ≤ 1 koşulunu bozar', ['Doğrudur ve r = 1,2\'dir', 'Doğrudur ve r = 0,6\'dır', 'Doğrudur ve r² = 1,2\'dir'], 'b_yx·b_xy = r² ≤ 1 olmalıdır; 2·0,6 = 1,2 bu koşulu sağlamadığı için bir hesap hatası vardır.'),
  ('Aynı veriden elde edilen iki regresyon doğrusundan 3x + 2y = 26 doğrusu y\'nin x\'e göre, 6x + y = 31 doğrusu x\'in y\'ye göre doğrusu ise korelasyon katsayısı kaçtır?', '−0,5', ['0,5', '−0,25', '−2'], 'y|x eğimi −1,5; x|y doğrusu x = (31 − y)/6 için eğim −1/6. Çarpım 0,25 → |r| = 0,5; eğimler negatif olduğundan r = −0,5.'),
  ('Bir deneyde x değerlerinin standart sapması iki katına çıkarılacak biçimde daha geniş bir aralıkta ölçüm yapılıyor (n ve s aynı). Eğimin standart hatası nasıl değişir?', 'Yarıya iner', ['İki katına çıkar', 'Dörtte birine iner', 'Değişmez'], 'Sxx, x\'in standart sapmasının karesiyle orantılıdır; sapma iki katına çıkınca Sxx dört kat, √Sxx iki kat artar ve SE(b) yarıya düşer.'),
  ('Bir veri setine ortalama noktası (x̄, ȳ)\'nin kendisi yeni bir gözlem olarak ekleniyor. Regresyon doğrusunun eğimi ve Pearson r nasıl etkilenir?', 'İkisi de değişmez', ['Eğim değişir, r değişmez', 'Eğim değişmez, r azalır', 'İkisi de sıfıra yaklaşır'], 'Yeni nokta sapma toplamlarına (Sxx, Syy, Sxy) hiçbir şey eklemez, ortalamalar da aynı kalır; eğim b = Sxy/Sxx ve r = Sxy/√(SxxSyy) değişmez.'),
  ('İki ilçede kişi başına suç sayısı ve kişi başına polis sayısı, her ikisi de nüfusa bölünerek hesaplanmıştır ve aralarında yüksek bir korelasyon bulunmuştur. Bu korelasyonun yapay biçimde şişmesinin olası nedeni nedir?', 'Ortak paydanın (nüfusun) iki orana da girmesi', ['Polislerin suçları artırması', 'Verinin küçük olması yüzünden r\'nin hep 1 olması', 'Nüfus bölünmesinin korelasyonu her zaman sıfırlaması'], 'Aynı değişkene bölünen iki oran, paydanın değişimiyle birlikte hareket eder; bu da gerçek bir ilişki olmasa bile sahte bir korelasyon üretebilir.'),
  ('Z değişkeni hem X\'i hem Y\'yi etkiliyor ve Z sabitlendiğinde X ile Y ilişkisiz kalıyor. r_xz = 0,8 ve r_yz = 0,5 ise X ile Y arasında beklenen korelasyon kaçtır?', '0,4', ['1,3', '0,65', '0,25'], 'Z sabitken ilişki sıfırsa r_xy = r_xz·r_yz = 0,8·0,5 = 0,4 olmalıdır.'),
  ('İki ayrı çalışmadan birinde (n = 40) r = 0,60, ötekinde (n = 40) r = 0,50 bulunmuştur. Bu fark hakkında hangisi söylenebilir?', 'İkisi arasındaki fark küçük örneklemde rastlantısal olabilir', ['Birinci çalışma kesinlikle daha güvenilirdir', 'İkinci çalışma hatalıdır', 'İkisinin kitle korelasyonları kesinlikle farklıdır'], '40 gözlemde r\'nin standart hatası yaklaşık 0,12–0,15 mertebesindedir; 0,10\'luk fark bu belirsizlik içinde kalır.'),
  ('Bir veri setinde x: 2, 4, 6, 8, 10, 12, 14 ve y: 5, 4, 6, 7, 9, 8, 11\'dir. Bu veriyle y\'nin x\'e göre regresyon doğrusunun eğimi 0,518 ve r = 0,928 ise y\'nin standart sapmasının x\'in standart sapmasına oranı yaklaşık kaçtır?', '0,56', ['0,485', '1,79', '0,93'], 'b = r·(sy/sx) → sy/sx = 0,518/0,928 ≈ 0,558.'),
  ('Aynı reklam verisinde (bütçe 5–25, satış 12, 20, 29, 35, 48) ŷ = 2,7 + 1,74x modeli için artık kareler toplamı yaklaşık kaçtır?', '9,9', ['2,5', '0,6', '19,8'], 'Artıklar: 0,6; −0,1; 0,2; −2,5; 1,8. Kareler: 0,36+0,01+0,04+6,25+3,24 = 9,9.'),
  ('n = 6, Σx = 21, Σx² = 91, Σy = 48 ve Σxy = 190 olan veride en küçük kareler eğimi yaklaşık kaçtır?', '1,26', ['1,505', '0,63', '2,00'], 'b = (6·190 − 21·48)/(6·91 − 441) = (1140 − 1008)/105 = 132/105 ≈ 1,26.'),
  ('x = 1, 2, 3, 4 için nΣx² − (Σx)² ifadesinin değeri kaçtır ve bu nicelik neyin n katıdır?', '20; x\'in sapma kareler toplamının (Sxx) n katı', ['30; x\'in ortalamasının karesinin n katı', '10; Σx\'in yarısının', '100; Σx\'in karesinin'], '4·30 − 100 = 20 ve Sxx = 5 olduğundan 20 = n·Sxx.'),
  ('x = 1, 2, 3, 4 olan bir regresyonda e₁ = 2 ve e₂ = −1\'dir. e₃ ve e₄ kaçtır?', 'e₃ = −4, e₄ = 3', ['e₃ = −1, e₄ = 0', 'e₃ = 3, e₄ = −4', 'e₃ = −2, e₄ = 1'], 'Σe = 0 → e₃ + e₄ = −1; Σxe = 0 → 2 − 2 + 3e₃ + 4e₄ = 0. Çözülünce e₄ = 3, e₃ = −4.'),
  ('r_xy = 0,9 ve r_yz = 0,9 ise r_xz için aşağıdaki değerlerden hangisi imkânsızdır?', '0,5', ['0,7', '0,9', '0,65'], 'Korelasyon matrisi yarı pozitif tanımlı olmalıdır; bu durumda r_xz ≥ 2·0,81 − 1 = 0,62 olmak zorundadır. 0,5 bu sınırın altındadır.'),
  ('r_xy = 0,6 ve r_yz = 0,8 ise r_xz\'in alabileceği en küçük ve en büyük değerler (yarı pozitif tanımlılık koşuluyla) kaçtır?', '0 ile 0,96', ['0,48 ile 0,96', '−0,48 ile 0,48', '0,2 ile 0,8'], 'r_xz ∈ r_xy·r_yz ± √[(1−r_xy²)(1−r_yz²)] = 0,48 ± √(0,64·0,36) = 0,48 ± 0,48 → [0; 0,96].'),
  ('Şapma (hat) matrisi H = X(X′X)⁻¹X′ için iz(H) kaçtır?', 'Parametre sayısı', ['Gözlem sayısı n', '1', 'k − 1'], 'İz, kaldıraç değerlerinin toplamıdır ve izdüşüm matrisinin rankına, yani parametre sayısına eşittir.'),
  ('ln(maaş) = 2 + 0,08·eğitim_yılı + 0,3·yönetici modelinde (yönetici: 0/1) yöneticilik, diğer koşullar eşitken maaşı yaklaşık yüzde kaç değiştirir?', 'Yaklaşık %35 artırır', ['Yaklaşık %0,3 artırır', 'Yaklaşık %30 artırır, çünkü katsayı 0,3\'tür', 'Yaklaşık %3 artırır'], 'Tam yüzde değişim e^0,3 − 1 ≈ 0,35\'tir; 100·b yaklaşımı (%30) yalnızca küçük katsayılarda iyidir, 0,3 gibi büyükçe değerlerde sapar.'),
  ('Bir analizde x₁ ile x₂ birbirinden bağımsız (r = 0) iken y ile ilişkileri r₁ = 0,6 ve r₂ = 0,5\'tir. İkisiyle birlikte kurulan modelin R²\'si kaçtır?', '0,61', ['0,555', '0,30', '0,85'], 'Bağımsız açıklayıcılarda R² = r₁² + r₂² = 0,36 + 0,25 = 0,61.'),
  ('Haftalık sayım verisi için Poisson regresyonunda ln(μ) = 0,5 + 0,2x bulunmuştur. x bir birim artarsa beklenen sayı yaklaşık kaç katına çıkar?', '1,22 katına', ['0,2 katına', '1,20 katına tam olarak', '0,5 katına'], 'e^0,2 ≈ 1,221; beklenen sayı yaklaşık %22 artar.'),
  ('Aynı Poisson modelinde (ln μ = 0,5 + 0,2x) x = 0 için beklenen sayı yaklaşık kaçtır?', '1,65', ['0,5', '0,2', '1,225'], 'μ = e^0,5 ≈ 1,649.'),
  ('Bir yönetici, fiyat arttıkça satışın değiştiğini görüyor; ancak fiyat, talebin yüksek olduğu dönemlerde de artırılıyor. Bu durum için hangi sorun akla gelir?', 'Eşanlılık/içsellik; fiyat hata terimiyle ilişkili olabilir', ['Çoklu doğrusal bağlantı', 'Tavan etkisi', 'Örnekleme hatasının sıfır olması'], 'Talep şokları hem fiyatı hem satışı etkilediğinden fiyat içseldir; sıradan en küçük karelerle bulunan eğim fiyatın nedensel etkisini yansıtmaz.'),
  ('Araç değişken (instrument) yaklaşımında geçerli bir araç hangi iki koşulu sağlamalıdır?', 'İçsel açıklayıcıyla ilişkili olmalı ve y\'yi yalnızca o açıklayıcı üzerinden etkilemelidir', ['y ile mükemmel korelasyonlu olmalı ve hata terimine bağlı olmalıdır', 'Rastgele sayılardan oluşmalı ve açıklayıcıyla ilişkisiz olmalıdır', 'Modeldeki en büyük katsayıya sahip olmalıdır'], 'Geçerli araç hem ilgili (relevance) hem dışsal (exogeneity) olmalıdır; yani hata terimiyle ilişkisiz ve y\'ye doğrudan etkisiz olmalıdır.'),
  ('Aynı bireylerin yıllar içinde izlendiği panel verisinde \'sabit etkiler\' (fixed effects) yaklaşımı hangi sorunu çözmeye yardımcı olur?', 'Bireye özgü ve zamanla değişmeyen gözlenmeyen farkların yanlılığını', ['Hata varyansının sıfırlanmasını', 'Gözlem sayısının küçüklüğünü', 'Bağımlı değişkenin normalleştirilmesini'], 'Her birey kendi ortalamasına göre karşılaştırıldığı için zamanla sabit gözlenmeyen özellikler (yetenek gibi) modelden arındırılır.'),
  ('Bir araştırmacı, etkisini ölçmek istediği X\'in sonuca bir aracı değişken üzerinden ulaştığını bilmesine rağmen o aracıyı da kontrol değişkeni olarak modele koyuyor. Sonuç ne olur?', 'X\'in toplam etkisinin bir kısmı kontrol edilerek ortadan kalkar', ['X\'in etkisi her zaman tam olarak ölçülür', 'Katsayı kesinlikle büyür', 'Model çözülemez'], 'Aracı değişkeni sabitlemek, X\'in o yol üzerinden iletilen etkisini engeller; böylece yalnızca doğrudan etki kalır.'),
  ('Modele y ile ilişkisi olmayan bir açıklayıcı değişken eklenirse diğer katsayıların yansızlığı ve varyansları için ne söylenebilir?', 'Yansız kalırlar, ama varyansları artabilir', ['Bütün katsayılar yanlı olur ve varyansları da küçülür', 'Varyansları kesinlikle küçülür, çünkü gözlem sayısı artmıştır', 'Katsayılar sıfıra eşitlenir'], 'Gereksiz değişken yanlılık yaratmaz; fakat serbestlik derecesini azaltır ve ilişkiliyse standart hataları şişirir.'),
  ('Granger ve Newbold\'un 1974\'te dikkat çektiği \'sahte regresyon\' sorununa göre, birbirinden bağımsız iki rastgele yürüyüş serisi regresyona sokulursa sık sık ne görülür?', 'Yüksek R² ve anlamlı görünen eğim, ama düşük Durbin–Watson değeri', ['R² her zaman sıfır çıkar ve eğim anlamsızdır', 'Eğim hep tam 1 çıkar ve artıklar bağımsızdır', 'Durbin–Watson her zaman 2 çıkar'], 'Durağan olmayan serilerde ortak stokastik eğilimler yapay bir ilişki üretir; artıkların güçlü otokorelasyonu (düşük DW) bu sorunun ipucudur.'),
  ('Durağan olmayan iki zaman serisinin bir doğrusal birleşimi durağansa bu iki seriye ne ad verilir?', 'Eşbütünleşik (cointegrated) seriler', ['Birbirinden tamamen bağımsız seriler', 'Mevsimsel dalgalanması olan seriler', 'Ortak normal seriler'], 'Eşbütünleşme, ayrı ayrı kalıcı dalgalanan serilerin uzun dönemde ortak bir denge ilişkisini paylaşması demektir.'),
  ('Chow testi, bir regresyon modelinde hangi hipotezi sınamak için kullanılır?', 'Katsayıların iki alt örneklem (örneğin iki dönem) arasında eşit olup olmadığını', ['Hataların normal dağılıp dağılmadığını', 'Açıklayıcılar arası çoklu doğrusal bağlantıyı', 'Kaldıraç noktası bulunup bulunmadığını'], 'Yapısal kırılma testi olan Chow testi, modelin iki dönemde aynı katsayılarla geçerli olup olmadığını sorar.'),
  ('Ortalamadan çok uzak olmayan (x ≈ x̄) ama y değeri diğerlerinden çok farklı olan tek bir gözlem, regresyon doğrusunu esas olarak nasıl etkiler?', 'Eğimi pek değiştirmez, daha çok sabit terimi (doğrunun yüksekliğini) kaydırır', ['Eğimi tamamen tersine çevirir ve r\'yi −1 yapar', 'Hiçbir parametreyi etkilemez, çünkü x̄\'ye yakındır', 'Yalnızca kaldıracı büyütür'], 'x̄\'ye yakın bir noktanın kaldıracı düşüktür; eğim üzerindeki etkisi küçük olur ama ȳ\'yi ve dolayısıyla kesişimi kaydırır.'),
  ('Bir yazı yazma hızı çalışmasında bireyler arasında hız ile hata sayısı pozitif ilişkilidir (hızlı yazanlar daha çok hata yapar), fakat her bireyin kendi içinde hızlandığı günlerde hata sayısı azalmaktadır. Bu çelişki nasıl açıklanır?', 'Bireyler arası ve birey içi ilişkiler farklı olabilir; birleşik veri ikisini karıştırır', ['Hesap hatası vardır, ikisi aynı olmak zorundadır', 'Pearson r bireysel verilerle hesaplandığında tanımsızdır', 'Hata sayısı ile hız arasında hiçbir ilişki yoktur ve veri yanlıştır'], 'Gruplar arası (between) ve grup içi (within) korelasyonlar farklı işaret taşıyabilir; ayrıştırma gerekir.'),
  ('Bir seri için yt = 6 + 0,7·y(t−1) şeklinde birinci dereceden otoregresif model kurulmuştur. Serinin uzun dönem ortalaması (durağan düzey) a/(1−b) ile kaçtır?', '20', ['6', '8,6', '42'], 'μ = 6/(1 − 0,7) = 6/0,3 = 20.'),
  ('Basit sarkaç deneyinde T² ile uzunluk L arasında regresyon eğimi 4,0 s²/m çıkmıştır. T² = (4π²/g)·L bağıntısına göre g yaklaşık kaçtır?', '9,87 m/s²', ['4,0 m/s²', '1,0 m/s²', '39,5 m/s²'], 'Eğim 4π²/g = 4,0 → g = 4π²/4 = π² ≈ 9,87 m/s².'),
  ('Bir tepkime hızı sabitinin Arrhenius çizimi (ln k – 1/T regresyonu) eğimi −5000 K\'dir. Eğim −Ea/R ise ve R = 8,314 J/(mol·K) alınırsa aktivasyon enerjisi yaklaşık kaç kJ/mol\'dür?', '41,6', ['5,0', '0,6', '415,7'], 'Ea = −eğim·R = 5000·8,314 ≈ 41 570 J/mol ≈ 41,6 kJ/mol.'),
  ('Doz–yanıt modelinde kesişim −0,5 mmHg çıkmıştır. Bu negatif kesişim için en makul yorum nedir?', 'Sıfır doz için tahmin sıfıra çok yakındır; küçük fark örnekleme değişkenliğinden olabilir', ['Doz sıfırken tansiyon kesin olarak yarım birim yükselir', 'İlaç zararlıdır', 'Model hatalıdır ve tümüyle atılmalıdır'], 'Kesişimin sıfırdan farkı standart hatasına göre küçükse rastlantı sayılabilir; yorum, x = 0\'ın anlamlı olup olmadığına bağlıdır.'),
  ('Tahmin hatasının standart sapmasını y\'nin ham standart sapmasının yarısına indirmek için gereken korelasyon (mutlak değerce) yaklaşık kaçtır?', '0,87', ['0,505', '0,75', '0,25'], '√(1−r²) = 0,5 → r² = 0,75 → r ≈ 0,866. Tahmin hatasını yarıya indirmek için oldukça güçlü bir ilişki gerekir.'),
  ('r = 0,6 olan bir ilişkiden yararlanılarak yapılan tahminlerde hata standart sapması, hiçbir açıklayıcı kullanılmayan duruma göre yaklaşık yüzde kaç küçülür?', '%20', ['%36,5', '%60', '%64'], 'Artık SD/sy = √(1−0,36) = 0,8; yani yalnız %20 azalma sağlanır. R² %36 olsa da hata SD\'sindeki düşüş bundan küçüktür.'),
  ('n = 21, sx = 3 ve eğim b = 0,5 ise regresyonla açıklanan kareler toplamı (SSR = b²·Sxx) kaçtır?', '45', ['4,5', '90', '22,5'], 'Sxx = (n−1)·sx² = 20·9 = 180; SSR = 0,25·180 = 45.'),
  ('Aynı veride (n = 21, SSR = 45) y\'nin standart sapması 4 ise R² yaklaşık kaçtır?', '0,14', ['0,505', '0,28', '0,07'], 'SST = (n−1)·sy² = 20·16 = 320; R² = 45/320 ≈ 0,14.'),
  ('Bir regresyonda R² = 0,25 ve n = 27 ise F istatistiği F = R²(n−2)/(1−R²) ile kaçtır?', '8,33', ['0,33', '6,25', '25'], 'F = 0,25·25/0,75 = 8,33; serbestlik dereceleri 1 ve 25\'tir.'),
  ('Bir veri setinde Sxx = 50, Syy = 200 ve R² = 0,81 ise regresyon eğiminin mutlak değeri kaçtır?', '1,8', ['3,24', '0,9', '4'], '|r| = 0,9; |b| = |r|·√(Syy/Sxx) = 0,9·√4 = 1,8.'),
  ('11 gözlemde r = −0,6 bulunmuştur (9 sd, %5 iki yönlü t* = 2,262). t değeri ve karar hangisidir?', 't = −2,25; sınırda reddedilemez', ['t = −2,25; reddedilir', 't = −0,6; reddedilir', 't = −3,6; reddedilemez'], 't = −0,6·3/0,8 = −2,25 ve |−2,25| < 2,262; değer eşiğe çok yakındır ama H0 reddedilemez.'),
  ('102 çiftlik bir örneklemde (100 sd, %5 iki yönlü t* ≈ 1,98) anlamlı sayılabilecek en küçük |r| yaklaşık kaçtır? (r = t/√(t² + sd))', '0,19', ['0,105', '0,35', '0,50'], 'r = 1,98/√(3,92 + 100) ≈ 0,194. Büyük örneklemde çok zayıf korelasyonlar bile anlamlı çıkabilir.'),
  ('27 çiftlik bir örneklemde (25 sd, t* = 2,06) iki yönlü %5 düzeyinde anlamlı olmak için |r| en az yaklaşık kaç olmalıdır?', '0,38', ['0,205', '0,50', '0,06'], 'r = 2,06/√(4,24 + 25) ≈ 0,38.'),
  ('1002 çiftlik çok büyük bir örneklemde (1000 sd, t* ≈ 1,96) anlamlı olmak için gereken en küçük |r| yaklaşık kaçtır?', '0,06', ['0,205', '0,01', '0,30'], 'r = 1,96/√(3,84 + 1000) ≈ 0,062; çok küçük bir ilişki bile anlamlı bulunur, bu da anlamlılığın pratik önem demek olmadığını gösterir.'),
  ('İki bağımsız örneklemde (n = 103 ve 103) r₁ = 0,50 ve r₂ = 0,25\'tir. Fisher z′ değerleri 0,549 ve 0,255, fark için SE = √(1/100 + 1/100) ≈ 0,141 ise z istatistiği ve karar nedir?', 'z ≈ 2,08; %5 düzeyinde korelasyonlar farklıdır', ['z ≈ 2,08; korelasyonlar farklı değildir', 'z ≈ 0,25; farklıdır', 'z ≈ 4,00; farklı değildir'], 'z = (0,549 − 0,255)/0,141 ≈ 2,08 > 1,96; iki bağımsız korelasyon arasındaki fark anlamlıdır.'),
  ('n = 53 ve r = 0,7 iken H0: ρ = 0,5 sınanıyor (z′₀ = 0,549; z′ = 0,867; SE = 1/√50 ≈ 0,141). z istatistiği ve karar nedir?', 'z ≈ 2,25; %5 düzeyinde reddedilir', ['z ≈ 2,25; reddedilemez', 'z ≈ 6,13; reddedilemez', 'z ≈ 0,32; reddedilir'], 'z = (0,867 − 0,549)/0,141 ≈ 2,25 > 1,96 olduğundan ρ = 0,5 hipotezi reddedilir.'),
  ('Kısmi korelasyon ile yarı kısmi (semi-partial) korelasyon arasındaki fark nedir?', 'Yarı kısmi korelasyonda üçüncü değişkenin etkisi yalnızca bir değişkenden ayıklanır', ['İkisi tamamen aynı niceliktir', 'Kısmi korelasyon yalnızca sıra verilerine uygulanır', 'Yarı kısmi korelasyonda hiçbir değişken sabitlenmez'], 'Kısmi korelasyonda z\'nin etkisi hem x\'ten hem y\'den, yarı kısmi korelasyonda yalnızca birinden (genellikle x\'ten) çıkarılır.'),
  ('Sıradan en küçük kareler yerine mutlak sapmaların toplamını en aza indiren (en küçük mutlak sapma) regresyon, koşullu dağılımın hangi özetini tahmin eder?', 'Koşullu ortancayı', ['Koşullu ortalamayı', 'Koşullu varyansı', 'Koşullu modu'], 'Mutlak hataların toplamı ortancada en küçüktür; bu yüzden LAD regresyonu medyan regresyonudur ve uç değerlere daha dayanıklıdır.'),
  ('Kuantil regresyon, sıradan regresyona göre hangi bakımdan farklı bir bilgi verir?', 'Yanıtın dağılımının yalnızca ortasını değil, farklı dilimlerini (örneğin %10, %90) modeller', ['Yalnız ortalamayı daha iyi tahmin eder', 'Yalnızca kategorik veriler için kullanılır', 'Hataların normal olmasını zorunlu kılar'], 'Farklı kuantiller için ayrı eğimler kestirilir; bu da açıklayıcının üst ve alt uçlardaki etkisinin farklı olabildiği durumları ortaya çıkarır.'),
  ('LOESS (yerel ağırlıklı regresyon) yönteminin tanımlayıcı özelliği nedir?', 'Her x çevresinde yakın gözlemlere daha çok ağırlık veren yerel uydurma yapması', ['Tüm veriye tek bir global doğru uydurması', 'Yalnızca kategorik açıklayıcılarla çalışması', 'Hiçbir ağırlık kullanmaması'], 'LOESS, her noktada komşu gözlemlerle (azalan ağırlıklarla) yerel bir doğru ya da polinom uydurur; böylece genel bir parametrik biçim varsaymadan eğrisel ilişkiyi izler.'),
  ('Aynı verilere ln(y) üzerinden doğrusal model uydurmak ile y\'ye üstel bir eğriyi doğrudan doğrusal olmayan en küçük karelerle uydurmak her zaman aynı parametreleri verir mi?', 'Hayır; çünkü iki yöntem hataları farklı ölçekte (log ya da orijinal) en aza indirir', ['Evet; çünkü logaritma doğrusal bir işlemdir', 'Evet; çünkü her iki durumda aynı veri vardır', 'Hayır; çünkü logaritmayla veri sayısı azalır'], 'Log ölçeğinde kareler toplamı en küçüklenirken büyük y değerlerinin göreli hataları ön plandadır; orijinal ölçekte ise mutlak hatalar. Bu yüzden tahminler farklı olabilir.'),
  ('Bir regresyon modelinde yanlılık (bias) ve varyans arasındaki ödünleşim (trade-off) ne anlatır?', 'Esnekliği artırmak yanlılığı azaltabilir ama kestirimin varyansını artırabilir', ['Yanlılık ve varyans her zaman birlikte artar', 'Yanlılığı azaltmak her zaman varyansı da azaltır', 'İkisi de modelin karmaşıklığından bağımsızdır'], 'Basit modeller yanlı (sistematik hatalı) ama kararlı; karmaşık modeller yansızlığa yakın ama örneğe duyarlı olur.'),
  ('Bir verinin iki alt grubunda ayrı ayrı güçlü pozitif eğim gözlenirken tümü birlikte alındığında eğim negatif çıkıyorsa regresyon modelinde bu durumu çözmek için hangi ekleme uygundur?', 'Grup değişkenini (kukla) modele katmak', ['Gözlem sayısını azaltmak', 'Bağımlı değişkeni sabitlemek', 'R² değerini düşürmek'], 'Grup farklarını kontrol eden bir kukla değişken, gruplar arası düzey farkını ayırır ve grup içi eğimi doğru biçimde tahmin etmeyi sağlar.'),
  ('Hastane düzeyinde yapılan bir çalışmada ortalama bekleme süresi ile ortalama memnuniyet arasında r = −0,9 çıkmıştır. Bu bulgudan \'bekleyen her hasta daha az memnundur\' sonucu neden doğrudan çıkmaz?', 'Grup ortalamalarındaki ilişki bireylerdeki ilişkiyi yansıtmak zorunda değildir', ['Ortalamalarla yapılan hesaplamalarda korelasyon katsayısı her zaman −1\'e eşit olduğu için bireysel ilişki zaten bilinir', 'Hastane sayısı küçük olamayacağı için ortalamalar bireysel değerlere eşittir', 'Bekleme süresinin birimi dakika olduğundan r bireysel düzeyde yalnızca pozitif çıkabilir'], 'Ekolojik yanılgı: toplulaştırılmış verilerde görülen ilişki bireylerde zayıf ya da farklı olabilir.'),
  ('Aynı bireylerden alınan her ölçümün bağımsız sayıldığı bir regresyonda her denekten 10 tekrar ölçüm vardır ve ölçümler ilişkilidir. Bu durumda standart hatalar için ne beklenir?', 'Olduğundan küçük hesaplanır; anlamlılık abartılır', ['Olduğundan büyük hesaplanır, hiçbir zaman anlamlı sonuç çıkmaz', 'Aynen doğru hesaplanır, çünkü tekrar ölçüm bilgi katmaz', 'Her zaman sıfır olur'], 'Tekrar ölçümler bağımsız değilse etkin örneklem sayısı gözlem sayısından küçüktür; bağımsız varsayan formüller standart hatayı hafife alır.'),
  ('ŷ = 4 + 2x modelinde x yeniden u = (x − 10)/5 olarak ölçekleniyor. ŷ\'nin u\'ya göre doğrusunda sabit ve eğim kaçtır?', 'Sabit 24, eğim 10', ['Sabit 4, eğim 0,4', 'Sabit 24, eğim 0,4', 'Sabit 14, eğim 2'], 'x = 5u + 10 olduğundan ŷ = 4 + 2(5u + 10) = 24 + 10u.'),
  ('İki grupta ayrı ayrı eğimler 2 (Sxx = 10) ve 4 (Sxx = 30) bulunmuştur. Grup içi ortak (havuzlanmış) eğim, Sxx ile ağırlıklandırılırsa kaç olur?', '3,5', ['3', '3,0·√2', '2,5'], '(2·10 + 4·30)/(10 + 30) = 140/40 = 3,5; daha fazla x değişkenliği olan grup eğime daha çok ağırlık verir.'),
  ('x değerleri ortalamaya göre merkezlenmişse (x̄ = 0), σ² = 4 ve n = 10 için sabit terim tahmininin varyansı kaçtır?', '0,4', ['0,16', '4', '0,04'], 'Merkezlenmiş x ile a = ȳ olur; Var(a) = σ²/n = 0,4.'),
  ('σ² = 4, x̄ = 5 ve Sxx = 20 iken sabit terim ile eğim tahminlerinin kovaryansı Cov(a, b) = −x̄σ²/Sxx kaçtır?', '−1', ['1', '−0,2', '−4'], '−5·4/20 = −1; x̄ pozitifken kesişim ve eğim tahminleri ters yönde ilişkilidir.'),
  ('s = 2, n = 10, Sxx = 40 ve x₀ − x̄ = 4 iken x₀ noktasındaki ortalama yanıtın tahmin standart hatası s·√(1/n + (x₀−x̄)²/Sxx) kaçtır?', '1,41', ['0,715', '2,45', '0,5'], '√(0,1 + 16/40) = √0,5 ≈ 0,707; 2·0,707 = 1,41.'),
  ('Aynı veride (s = 2, n = 10, Sxx = 40, x₀ − x̄ = 4) x₀ için yeni bir gözlemin tahmin standart hatası s·√(1 + 1/n + (x₀−x̄)²/Sxx) kaçtır?', '2,45', ['1,415', '3,0', '2,0'], '2·√(1 + 0,5) = 2·1,2247 ≈ 2,45.'),
  ('n = 10 gözlem, 0 ile 10 arasındaki x değerlerine nasıl yerleştirilirse eğimin standart hatası en küçük olur ve en büyük Sxx kaçtır?', 'Yarısı 0\'a, yarısı 10\'a konur; Sxx = 250', ['Eşit aralıklı yerleştirilir; Sxx = 250', 'Tümü 5\'e konur; Sxx = 250', 'Yarısı 0\'a, yarısı 10\'a konur; Sxx = 100'], 'Sxx\'i en büyüten yerleşim uç noktalardır: 10·5² = 250. Bu tasarım eğimi en duyarlı ölçer, ama doğrusallığı sınamaya uygun değildir.'),
  ('Ölçülen x değerleri 3 farklı düzeyden oluşan bir deneyde (ör. 0, 5, 10) her düzeyde birkaç tekrar var. Bu tasarımın doğrusal model dışındaki bir avantajı nedir?', 'Düzey içi saf hata sayesinde uyum eksikliği (lack-of-fit) sınanabilir', ['Hata varyansı kesinlikle sıfır olur', 'Eğim hesaplanamaz hâle gelir', 'Artıkların toplamı sıfırdan farklı olur'], 'Aynı x\'te tekrar ölçüm saf hatayı verir; model hatasının saf hatayla karşılaştırılması doğrusal model yeterliliğini sınar.'),
  ('Bir regresyonda yalnızca iki x düzeyi (0 ve 10) kullanılmış, her düzeyde 5 gözlem vardır. Bu tasarımla hangi sorun cevaplanamaz?', 'İlişkinin 0 ile 10 arasında doğrusal olup olmadığı', ['Eğimin sıfırdan farklı olup olmadığı', 'Düzeyler arasındaki ortalama fark', 'Hata varyansının büyüklüğü'], 'İki nokta her zaman doğrusal düzende görünür; ara bölgede eğrisellik olup olmadığı veriyle sınanamaz.'),
  ('lnL = −120, k = 3 ve n = 100 olan bir modelde BIC = k·ln(n) − 2lnL yaklaşık kaçtır? (ln 100 ≈ 4,605)', '253,8', ['246,05', '243,0', '258,4'], '3·4,605 = 13,8; 13,8 + 240 = 253,8. n büyüdükçe BIC cezası AIC\'den ağır basar.'),
  ('Mallows Cp ölçütünde, Cp değeri model parametre sayısı p\'ye yakınsa bu ne anlama gelir?', 'Modelin yanlılığının küçük olduğuna', ['Modelin çok yanlı olduğuna ve değişken eksikliğine', 'Hata varyansının tam olarak sıfır olduğuna', 'Verinin normal dağılmadığına'], 'Cp ≈ p, kestirim hatasının büyük kısmının varyanstan kaynaklandığını, sistematik hatanın az olduğunu gösterir.'),
  ('Modele eklenen bir değişken R²\'yi 0,20\'den 0,30\'a çıkarıyor. Bu değişkenin yerel etki büyüklüğü f² = (R²_tam − R²_dar)/(1 − R²_tam) yaklaşık kaçtır?', '0,14', ['0,105', '0,50', '0,33'], '(0,30 − 0,20)/(1 − 0,30) = 0,10/0,70 ≈ 0,14; orta düzeye yakın bir katkıdır.'),
  ('ρ = 0,3\'ü %80 güçle ve %5 iki yönlü anlamlılık düzeyinde saptamak için gereken yaklaşık n = [(1,96 + 0,84)/z′]² + 3 formülüyle (z′ = arctanh 0,3 ≈ 0,31) kaçtır?', '85', ['30', '150', '50'], '(2,80/0,3095)² + 3 ≈ 81,8 + 3 ≈ 85. Küçük bir korelasyonu güvenle yakalamak için onlarca gözlem gerekir.'),
  ('Üç değişkenli bir korelasyon matrisinde r₁₂ = 0,8, r₁₃ = −0,8 ise r₂₃ için hangisi mümkündür?', '−0,28 ile −1 arasında bir değer', ['+0,5', '+0,9 ile +1 arasında bir değer', '0 olması da mümkündür'], 'Yarı pozitif tanımlılık için r₂₃ ≤ r₁₂r₁₃ + √[(1−r₁₂²)(1−r₁₃²)] = −0,64 + 0,36 = −0,28 olmalıdır; bu yüzden değer −1 ile −0,28 arasında kalır.'),
  ('Bir bilim insanı iki ölçüm arasında r = 0,6 buluyor ve her ikisinin güvenirliği 0,8. Zayıflama düzeltmesi sonrası gerçek korelasyon tahmini kaçtır?', '0,75', ['0,485', '0,60', '0,96'], 'r_gerçek = r/√(r_xx·r_yy) = 0,6/0,8 = 0,75.'),
  ('Sabit 100 km\'lik yolu 10, 20, 40, 50 km/sa hızlarla giden araçların hızı ile yolculuk süresi arasındaki Pearson ve Spearman katsayıları için hangisi doğrudur?', 'Pearson ≈ −0,92; Spearman = −1', ['Pearson = −1; Spearman = −1', 'Pearson ≈ −0,92; Spearman ≈ −0,92', 'Pearson = 0; Spearman = 0'], 'Süre = 100/hız ters orantılıdır, doğrusal değildir; Pearson tam −1 olmaz, ama sıralar tam ters olduğu için Spearman −1\'dir.'),
  ('x: 1, 2, 2, 4 ve y: 1, 3, 2, 4 verileri için ortalama sıralar x\'te 1; 2,5; 2,5; 4 ve y\'de 1; 3; 2; 4\'tür. Bu sıraların Pearson korelasyonu (bağlı Spearman) yaklaşık kaçtır?', '0,95', ['1,005', '0,80', '0,75'], 'Sıra sapmaları çarpımı toplamı 4,5; Sxx = 4,5, Syy = 5 → r = 4,5/√22,5 ≈ 0,949. Bağ olunca 1 − 6Σd²/… formülü yaklaşık kalır, Pearson-sıra yöntemi kesindir.'),
  ('Üç hakem dört ürünü sıraladı; ürünlerin sıra toplamları 5, 7, 9 ve 11\'dir. Kendall uyum katsayısı W = 12S/[m²(n³ − n)] (m = 3, n = 4) kaçtır?', '0,44', ['0,205', '0,75', '1,00'], 'Ortalama sıra toplamı 8; S = 9 + 1 + 1 + 9 = 20. W = 240/(9·60) ≈ 0,44; orta düzeyde uyum.'),
  ('Tetrakorik korelasyon hangi durumda kullanılır?', 'İki ikili değişkenin altında yatan sürekli normal değişkenler varsayıldığında', ['İki sürekli değişken doğrusal olmayan ilişkiliyse', 'Zaman serilerinde otokorelasyon için', 'Yalnızca üç değişkenli verilerde'], 'Tetrakorik, ikili görünen iki değişkenin aslında ortak normal bir sürekli yapının kesilmiş hâli olduğu varsayımıyla altta yatan korelasyonu kestirir.'),
  ('Biserial korelasyon, nokta çift serili korelasyondan hangi varsayımıyla ayrılır?', 'İkili değişkenin altında normal dağılımlı bir sürekli değişken yattığını varsayar', ['İkili değişkenin gerçekten iki doğal kategorili olduğunu varsayar', 'Yalnız sıra verilerinde hesaplanır', 'Hiçbir varsayım gerektirmez'], 'Biserial, yapay biçimde ikiye bölünmüş sürekli bir özellik için tasarlanır; doğal ikili (cinsiyet gibi) değişkenler için nokta çift serili uygundur.'),
  ('Mesafe korelasyonu (distance correlation) için aşağıdakilerden hangisi doğrudur?', 'Sıfır olması, değişkenlerin bağımsız olduğu anlamına gelir', ['Yalnız doğrusal ilişkiyi ölçer', 'Her zaman negatif olabilir', 'Sıfır olması hiçbir şey ifade etmez'], 'Székely ve arkadaşlarının önerdiği mesafe korelasyonu, eğrisel ilişkileri de yakalar ve yalnız bağımsızlık durumunda 0 olur.'),
  ('Karşılıklı bilgi (mutual information) ölçüsünün Pearson korelasyonuna göre bir üstünlüğü nedir?', 'Doğrusal olmayan bağımlılıkları da yakalayabilmesi', ['Yalnızca normal veride tanımlı olması', 'Her zaman −1 ile 1 arasında kalması', 'Hesaplanmak için hiçbir veri gerektirmemesi'], 'Karşılıklı bilgi, değişkenlerin bağımsız olması durumunda sıfırdır ve her türlü bağımlılıkta pozitiftir; Pearson yalnız doğrusal ilişkiye duyarlıdır.'),
  ('Mann–Kendall trend testi hangi niceliğe dayanır?', 'Gözlem değerleri ile zaman sırası arasındaki Kendall tau\'ya', ['Gözlem değerlerinin standart sapmasına', 'Artıkların Durbin–Watson değerine', 'Serinin ortalamasının sıfır olmasına'], 'Test, zaman ilerledikçe değerlerin artan mı azalan mı olduğunu uyumlu/uyumsuz çiftlerle ölçer; parametrik bir doğrusal biçim varsaymaz.'),
  ('Nokta çift serili korelasyon ile iki grup ortalaması arasındaki bağımsız örneklem t testi arasındaki ilişki nedir?', 'Aynı bilgiyi taşırlar; r_pb anlamlıysa t testi de anlamlıdır', ['İlişkileri yoktur', 'r_pb her zaman 1\'dir', 't testi yalnız üç grupta kullanılabilir'], 'İkili kukla ile sürekli değişkenin regresyonu, iki grup ortalama farkını sınayan t testiyle aynı t istatistiğini verir.'),
  ('Bağ içermeyen n = 4 gözlemde Kendall tau\'nun alabileceği değerler hangi kümededir?', '−1, −2/3, −1/3, 0, 1/3, 2/3, 1', ['−1 ile 1 arasında her değer', 'Yalnız −1 ve 1', '0 ile 1 arasında her değer'], '6 çift vardır; τ = (C − D)/6 ve C + D = 6 olduğundan τ yalnızca (6 − 2D)/6 değerlerini alabilir.'),
  ('İki açıklayıcılı modelde r₁y = 0,6, r₂y = 0,5 ve r₁₂ = 0,4\'tür. R² = β₁r₁y + β₂r₂y ve β₁ = (r₁y − r₂y·r₁₂)/(1 − r₁₂²) ile β₂ benzer biçimde alınırsa R² yaklaşık kaçtır?', '0,44', ['0,615', '0,36', '0,25'], 'β₁ ≈ 0,476 ve β₂ ≈ 0,310; R² = 0,476·0,6 + 0,310·0,5 ≈ 0,44. Açıklayıcılar ilişkili olduğundan R², r₁y² + r₂y² = 0,61\'den küçüktür.'),
  ('Aynı korelasyonlarla (r₁y = 0,6, r₂y = 0,5) açıklayıcılar arası ilişki r₁₂ = 0,6\'ya çıkarsa R² yaklaşık kaç olur?', '0,39', ['0,615', '0,44', '0,50'], 'β₁ = 0,469, β₂ = 0,219; R² = 0,469·0,6 + 0,219·0,5 ≈ 0,39. Açıklayıcılar birbirine yaklaştıkça ortak bilgi çoğalır, ek açıklama gücü azalır.'),
  ('r₁y = 0, r₂y = 0,5 ve r₁₂ = 0,5\'tir. x₁ tek başına y ile ilişkisiz olduğu hâlde iki değişkenli modelin R²\'si kaçtır ve bu olgu hangi adla anılır?', '≈ 0,33; baskılayıcı (suppressor) değişken etkisi', ['0,25; bağımsızlık', '0; tam ilişkisizlik', '0,50; çoklu doğrusal bağlantı'], 'β₁ = −0,333 ve β₂ = 0,667 olur; R² = 0,667·0,5 ≈ 0,33 > r₂y² = 0,25. x₁, x₂\'deki ilgisiz değişkenliği ayıklayarak açıklama gücünü artırır.'),
  ('R²_dar = 0,36 ve R²_tam = 0,45 ise ek değişkenin kısmi korelasyonu (mutlak) kaçtır? (kısmi r² = ΔR²/(1 − R²_dar))', '0,375', ['0,30', '0,14', '0,09'], 'Kısmi r² = 0,09/0,64 ≈ 0,141; kök alınca ≈ 0,375.'),
  ('İki açıklayıcı arasında r₁₂ = 0,8\'dir. Çoklu doğrusal bağlantı olmasaydı elde edilecek standart hataya göre eğimin standart hatası yaklaşık kaç kat olur?', '1,67', ['2,785', '0,6', '1,25'], 'Şişme √VIF = √2,78 ≈ 1,67\'dir.'),
  ('s = 3, Sxx = 36 ve r₁₂ = 0,8 iken x₁ katsayısının standart hatası SE = s/√[Sxx(1 − r₁₂²)] kaçtır?', '0,83', ['0,505', '1,39', '2,00'], '√(36·0,36) = 3,6; SE = 3/3,6 ≈ 0,83. Bağlantı olmasa 3/6 = 0,5 olurdu.'),
  ('Biri n = 12, k = 1, R² = 0,50; diğeri n = 12, k = 3, R² = 0,55 olan iki model için düzeltilmiş R²\'ler yaklaşık kaçtır ve hangisi tercih edilir?', '0,45 ve 0,38; birinci model', ['0,50 ve 0,55; ikinci model', '0,45 ve 0,38; ikinci model', '0,48 ve 0,52; ikinci model'], 'Birinci: 1 − 0,5·11/10 = 0,45; ikinci: 1 − 0,45·11/8 ≈ 0,38. Ek iki değişken, kayda değer katkı sağlamadığı için cezalandırılır.'),
  ('ΔR² = 0,09, tam model R² = 0,45, n = 33 ve tam modelde 2 açıklayıcı vardır (artık sd = 30). Eklenen tek değişkenin kısmi F istatistiği yaklaşık kaçtır?', '4,91', ['0,205', '9,00', '1,64'], 'F = (ΔR²/1)/[(1 − R²_tam)/30] = 0,09/(0,55/30) ≈ 4,91.'),
  ('Bir araştırmacı farklı marka motorlar için hız ve yakıt tüketimi verisini marka bazında ayrı ayrı analiz edip her markada negatif eğim, birleşik veride ise pozitif eğim buluyor. Hangi kavram uygulanabilir?', 'Gruplar arası ve grup içi ilişkilerin zıt işaretli olması', ['Çoklu doğrusal bağlantı ve açıklayıcıların birbirinden ayrışamaması', 'Otokorelasyon ve ardışık artıkların ilişkisi', 'Ölçüm güvenirliği ve testin tekrarlanabilirliği'], 'Marka etkisi ayrı bir yapı kurduğunda toplanmış veri, grup içi eğilimi tersine çevirebilir; marka kuklası ya da hiyerarşik model gerekir.'),
  ('n = 60, çarpıklık S = 0,5 ve basıklık K = 3,5 olan artıklar için Jarque–Bera JB = (n/6)[S² + (K−3)²/4] kaçtır? (χ²₂ %5 kritik değeri 5,99)', '3,13; normallik reddedilemez', ['31,3; normallik reddedilir', '0,31; normallik reddedilir', '3,13; normallik reddedilir'], 'JB = 10·(0,25 + 0,0625) = 3,125 < 5,99 olduğundan normallik hipotezi reddedilemez.'),
  ('Bir gözlemin artığı 6, s = 3 ve kaldıracı h = 0,75\'tir. Studentize artık e/(s√(1−h)) kaçtır?', '4', ['2', '0,5', '8'], 'Payda 3·√0,25 = 1,5; 6/1,5 = 4. Yüksek kaldıraç, artığı olduğundan küçük gösterdiği için düzeltme büyütür.'),
  ('Standartlaştırılmış (studentize) artığı 2, parametre sayısı p = 2 ve kaldıracı h = 0,5 olan bir gözlemin Cook uzaklığı D = (r²/p)·h/(1−h) kaçtır?', '2', ['1', '0,5', '4'], 'D = (4/2)·(0,5/0,5) = 2·1 = 2; bu değer 1\'in üzerinde olduğundan etkili bir gözlemdir.'),
  ('Bir gözlemin artığı 3 ve kaldıracı 0,5 ise PRESS (silinmiş) artığı e/(1 − h) kaçtır?', '6', ['1,5', '3', '9'], '3/(1 − 0,5) = 6; gözlem modele katılmasaydı tahmin hatası daha büyük olurdu.'),
  ('Added-variable (eklenmiş değişken) grafiği, çoklu regresyonda neyi görselleştirir?', 'Diğer açıklayıcılar sabitken bir değişkenin y ile kalan ilişkisini', ['Tüm açıklayıcıların toplam etkisini', 'Yalnız artıkların normalliğini', 'Sabit terimin güven aralığını'], 'Hem y\'nin hem ilgili x\'in diğer değişkenlere regresyonundan artıkları çizilir; eğim, çoklu regresyondaki katsayıya eşittir.'),
  ('Eksik veri içeren bir veri kümesinde her korelasyon, o iki değişkende bulunan tüm gözlemlerle hesaplanırsa (ikili silme) hangi sorun ortaya çıkabilir?', 'Elde edilen korelasyon matrisi tutarsız (pozitif yarı tanımlı olmayan) olabilir', ['Korelasyonların tamamı 1 olur', 'Matrisin köşegeni 0 olur', 'Korelasyonlar yalnız pozitif çıkar'], 'Her hücre farklı gözlem kümesine dayandığında matris tutarlılık koşulunu bozabilir; bu da sonraki çok değişkenli analizleri engeller.'),
  ('Hem x hem y\'nin ölçüm hatası taşıdığı durumda hata oranı biliniyorsa hangi regresyon türü önerilir?', 'Deming (hatalı değişkenli) regresyonu', ['Sıradan en küçük kareler', 'Lojistik regresyon', 'Ağırlıksız medyan regresyonu'], 'Deming regresyonu iki eksendeki ölçüm hatasını birlikte hesaba katar; yöntem karşılaştırma çalışmalarında kullanılır.'),
  ('Okul içindeki öğrencilerin başarısı okullara göre gruplanmışsa ve okullar farklı ortalamalara sahipse hangi model aile bu yapıyı doğrudan karşılar?', 'Okul için rastgele kesişimli karma etkili (çok düzeyli) model', ['Orijinden geçen doğrusal model', 'Yalnızca Spearman korelasyonu', 'Parçalı sabit model'], 'Aynı okuldan gelen öğrenciler bağımsız değildir; rastgele kesişim okullar arası değişkenliği ayrı bir varyans bileşeni olarak modeller.'),
  ('Çoklu doğrusal bağlantıyı azaltmak için birbirine çok yakın ölçüm yapan değişkenleri birleştiren bir yöntem hangisidir?', 'Ana bileşenler analizi ile bileşik değişken türetmek', ['Hata terimini sıfırlamak', 'Ağırlıklı en küçük kareler yöntemini kullanmak', 'Verinin ortalamasını çıkarmak'], 'Ana bileşenler, ilişkili değişkenlerin ortak varyansını birbirinden bağımsız birkaç bileşende toplar; bu bileşenler regresyonda kullanılabilir.'),
  ('İki sürekli değişken arasındaki korelasyon 0,5 iken biri medyandan ikiye bölünüp ikili hâle getirildiğinde ve Pearson hesaplandığında değer yaklaşık nasıl olur?', 'Yaklaşık 0,4; bilgi kaybı nedeniyle küçülür', ['Yaklaşık 0,5; değişmez', 'Yaklaşık 0,7; büyür', 'Tam 1,0\'a çıkar'], 'Medyan bölmesi normal veride korelasyonu yaklaşık 0,8 çarpanıyla küçültür: 0,5·0,8 ≈ 0,4.'),
  ('Sabit terimsiz (orijinden geçen) bir modelde en küçük kareler artıkları için hangisi geçerlidir?', 'Artıkların toplamı genelde sıfır olmaz', ['Artıkların toplamı her zaman sıfırdır ve model (x̄, ȳ)\'den geçer', 'Artıkların karesi her zaman sıfırdır, çünkü eğim serbesttir', 'Artıklar hep pozitiftir ve x ile ilişkisizdir'], 'Σe = 0 özelliği sabit terimin normal denkleminden gelir; sabit yoksa yalnızca Σxe = 0 sağlanır ve doğru ortalamalar noktasından geçmek zorunda değildir.'),
  ('Bir gözlem için ayrı bir kukla değişken (yalnız o gözlemde 1) modele eklenirse o gözlemin artığı ne olur?', 'Tam olarak sıfıra iner', ['İki katına çıkar ve standart hatayı büyütür', 'Değişmez, çünkü kukla eğimi etkilemez', 'Negatif bir sabite eşitlenir ve diğer artıkları da kaydırır'], 'Kukla, o gözlemi tek başına uyduracak serbestlik verir; gözlem fiilen modelden dışlanmış gibi davranır ve katsayıları diğer gözlemler belirler.'),
  ('Bir veri setindeki her gözlem birebir kopyalanarak (n iki katına çıkarılarak) aynı regresyon yeniden kuruluyor. Eğim, R² ve eğimin standart hatası nasıl değişir?', 'Eğim ve R² aynı kalır, standart hata yaklaşık √2 kat küçülür', ['Eğim iki katına çıkar, R² aynı kalır, standart hata değişmez', 'Eğim ve R² aynı kalır, standart hata değişmez', 'R² iki katına çıkar, eğim yarıya iner, standart hata sıfırlanır'], 'Kopyalama yeni bilgi eklemeden örneklem sayısını şişirir; tahminler aynı kalırken sanal biçimde daha dar güven aralıkları çıkar, bu yüzden bağımsız olmayan veriye güvenilmemelidir.'),
  ('Basit regresyonda 14 gözlem ve SSE = 48 iken SSE/n ile SSE/(n−2) kestirimleri arasındaki ilişki nedir?', 'SSE/n ≈ 3,43 olup yansız kestirim olan SSE/(n−2) = 4\'ten küçük kalır', ['SSE/n = 4 ve yansızdır, SSE/(n−2) ≈ 3,43\'tür', 'İkisi de 4\'tür', 'SSE/n = 3,43 ve yansız kestirimdir, 4 ise aşırı büyüktür'], 'SSE/n = 3,43, SSE/(n−2) = 4\'tür; ilki parametre kestiriminden dolayı hata varyansını sistematik olarak küçük bulur.'),
  ('Bir üretim fonksiyonu ln(Q) = 1,2 + 0,3·ln(K) + 0,7·ln(L) olarak kestirilmiştir (K: sermaye, L: emek, Q: üretim). Her iki girdi de %10 artarsa üretim yaklaşık nasıl değişir?', 'Yaklaşık %10 artar', ['Yaklaşık %3 artar ve emek etkisi yok sayılır', 'Yaklaşık %7 artar çünkü yalnızca emek etkilidir', 'Yaklaşık %100 artar çünkü katsayılar toplanıp çarpılır'], 'Log-log modelde katsayılar esnekliktir; toplamları 0,3 + 0,7 = 1 olduğundan ölçeğe sabit getiri vardır: girdilerin %10 artışı üretimi yaklaşık %10 artırır.'),
];
